export function transaction<T>(conn: DatabaseSync, fn: () => T): T {
  conn.exec('BEGIN IMMEDIATE')
  try {
    const result = fn()
    conn.exec('COMMIT')
    return result
  } catch (err) {
    conn.exec('ROLLBACK')
    throw err
  }
}
